    import sailpoint.object.*;
  	import sailpoint.object.QueryOptions;
  	import sailpoint.object.Filter;
  	import java.util.*;

  	QueryOptions qo=new QueryOptions();
  	qo.add(Filter.eq("manager.name","Jack.Sullivan")); // certification for employees under Jack.Sullivan
    List ids=context.getObjects(Identity.class,qo);

  	List <String> ids_list=new ArrayList< String>();
		for(Identity id: ids)
    {
    	ids_list.add(id.getName());
    }
  return ids_list;
